-- 149: Legg inn 6 nye premiummerker (Atabey, Byron, Ozgener Family, Patoro, Nestor Miranda, Saga).
-- Full data per vitola inkl. mal, dekkblad, styrke (1-5), smak og norsk beskrivelse.
-- Regulaer produksjon; enkelte rene limited/anniversary-utgaver er utelatt.

-- Byron: dekkbladvariant uoppgitt av produsent; kildene sier kun "ecuadoriansk".
UPDATE public.cigars SET wrapper_leaf='Ecuador'
WHERE brand='Byron' AND (wrapper_leaf IS NULL OR length(trim(wrapper_leaf))=0);
